<?php
declare(strict_types=1);
function pdf_escape(string $s): string { $s=iconv('UTF-8','Windows-1252//TRANSLIT//IGNORE',$s)?:$s; return str_replace(["\\","(",")","\r","\n"],["\\\\","\\(","\\)",' ',' '],$s); }
function sipacak_pdf(array $pages, string $title='SIPACAK'): string {
    $objects=[]; $add=static function(string $s)use(&$objects):int{$objects[]=$s;return count($objects);};
    $font=$add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>');
    $fontB=$add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>'); $pageIds=[];
    foreach($pages as $lines){$content='';$y=790;foreach($lines as $line){$text=(string)($line['text']??'');$size=(int)($line['size']??9);$x=(float)($line['x']??48);$bold=!empty($line['bold']);$leading=(float)($line['leading']??13);$content.="BT /".($bold?'F2':'F1')." {$size} Tf 1 0 0 1 {$x} {$y} Tm (".pdf_escape($text).") Tj ET\n";$y-=$leading;} $stream=$add('<< /Length '.strlen($content).">>\nstream\n".$content."endstream");$pageIds[]=$add('<< /Type /Page /Parent PAGESREF 0 R /MediaBox [0 0 595.28 841.89] /Resources << /Font << /F1 '.$font.' 0 R /F2 '.$fontB.' 0 R >> >> /Contents '.$stream.' 0 R >>');}
    $pagesObj=$add('');$objects[$pagesObj-1]='<< /Type /Pages /Kids ['.implode(' ',array_map(fn($p)=>$p.' 0 R',$pageIds)).'] /Count '.count($pageIds).' >>';foreach($pageIds as &$p)$objects[$p-1]=str_replace('PAGESREF',$pagesObj,$objects[$p-1]);unset($p);$catalog=$add('<< /Type /Catalog /Pages '.$pagesObj.' 0 R >>');$pdf="%PDF-1.4\n%\xE2\xE3\xCF\xD3\n";$offsets=[0];foreach($objects as $i=>$o){$offsets[$i+1]=strlen($pdf);$pdf.=($i+1)." 0 obj\n".$o."\nendobj\n";}$xref=strlen($pdf);$pdf.="xref\n0 ".(count($objects)+1)."\n0000000000 65535 f \n";for($i=1;$i<=count($objects);$i++)$pdf.=sprintf("%010d 00000 n \n",$offsets[$i]);$pdf.="trailer\n<< /Size ".(count($objects)+1)." /Root $catalog 0 R >>\nstartxref\n$xref\n%%EOF";return $pdf;
}
function sipacak_date_long(?string $date): string { if(!$date)return '-';$m=[1=>'Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];$t=strtotime($date);return date('j',$t).' '.$m[(int)date('n',$t)].' '.date('Y',$t); }
function sipacak_natural(array $items): string { $items=array_values(array_unique(array_filter(array_map('trim',$items))));$n=count($items);if(!$n)return '';if($n===1)return $items[0];if($n===2)return $items[0].' dan '.$items[1];$last=array_pop($items);return implode(', ',$items).', dan '.$last; }
function sipacak_destination(array $details): string { require_once __DIR__.'/../legacy_reference/includes/kwitansi_wilayah.php'; $villages=[];foreach($details as $d){$raw=trim((string)$d['desa']);$candidate=preg_replace('/^(?:desa|kelurahan)\s+/iu','',$raw);$mapped=kw_region_label((string)($d['kecamatan']??''),$raw);$label=$mapped??('Desa '.$candidate);$villages[$label]=true;}return sipacak_natural(array_keys($villages)); }
function sipacak_progress_pdf(PDO $pdo,int $progressId): string {
 require_once __DIR__.'/lpd_generator.php';
 $q=$pdo->prepare('SELECT ph.id_petugas,ph.id_kegiatan,ph.tanggal,p.nama_petugas,p.kecamatan FROM progress_harian ph JOIN petugas p ON p.id_petugas=ph.id_petugas WHERE ph.id_progress=?');
 $q->execute([$progressId]);$h=$q->fetch();if(!$h)throw new RuntimeException('Progress tidak ditemukan.');
 $s=$pdo->prepare("SELECT COUNT(*) total, SUM(CASE WHEN uraian_kegiatan IS NULL OR TRIM(uraian_kegiatan)='' OR output_tujuan IS NULL OR TRIM(output_tujuan)='' THEN 1 ELSE 0 END) incomplete FROM detail_progress WHERE id_progress=?");$s->execute([$progressId]);$quality=$s->fetch();if(!(int)$quality['total'])throw new RuntimeException('Detail progress belum tersedia.');if((int)$quality['incomplete']>0)throw new RuntimeException('LPD belum dapat dibuat karena uraian atau output pada sebagian detail belum lengkap.');
 $petugas=['id'=>(int)$h['id_petugas'],'nama_petugas'=>$h['nama_petugas'],'nama_kecamatan'=>$h['kecamatan']];
 return lpd_build_pdf($pdo,$petugas,(int)$h['id_kegiatan'],(string)$h['tanggal']);
}

function sipacak_download_pdf(string $pdf,string $filename): never {header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="'.preg_replace('/[^A-Za-z0-9_.-]/','_', $filename).'"');header('Content-Length: '.strlen($pdf));header('Cache-Control: private, no-store');echo $pdf;exit;}
function sipacak_read_excel_rows(string $path,string $ext): array {
 if($ext==='csv'){$f=fopen($path,'r');$out=[];while(($r=fgetcsv($f,0,','))!==false)$out[]=$r;fclose($f);return $out;}
 if($ext!=='xlsx'||!class_exists('ZipArchive'))throw new RuntimeException('File harus XLSX/CSV dan ekstensi ZipArchive aktif untuk XLSX.');$z=new ZipArchive();if($z->open($path)!==true)throw new RuntimeException('File XLSX tidak dapat dibuka.');$xml=$z->getFromName('xl/worksheets/sheet1.xml');$shared=$z->getFromName('xl/sharedStrings.xml');$strings=[];if($shared){preg_match_all('/<si\b[^>]*>(.*?)<\/si>/s',$shared,$sm);foreach($sm[1] as $si){preg_match_all('/<t\b[^>]*>(.*?)<\/t>/s',$si,$tm);$strings[]=html_entity_decode(implode('',$tm[1]),ENT_QUOTES|ENT_XML1,'UTF-8');}}if(!$xml){$z->close();throw new RuntimeException('Sheet pertama tidak ditemukan.');}$out=[];preg_match_all('/<row\b[^>]*>(.*?)<\/row>/s',$xml,$rm);foreach($rm[1] as $rx){$row=[];preg_match_all('/<c\b([^>]*)>(.*?)<\/c>/s',$rx,$cm,PREG_SET_ORDER);foreach($cm as $c){preg_match('/\br="([A-Z]+)\d+"/',$c[1],$m);$col=$m[1]??'A';$idx=0;foreach(str_split($col) as $ch)$idx=$idx*26+ord($ch)-64;$idx--; $v='';if(preg_match('/\bt="s"/',$c[1])&&preg_match('/<v>(\d+)<\/v>/',$c[2],$m))$v=$strings[(int)$m[1]]??'';elseif(preg_match('/<t\b[^>]*>(.*?)<\/t>/s',$c[2],$m))$v=html_entity_decode($m[1],ENT_QUOTES|ENT_XML1,'UTF-8');elseif(preg_match('/<v>(.*?)<\/v>/s',$c[2],$m))$v=html_entity_decode($m[1],ENT_QUOTES|ENT_XML1,'UTF-8');$row[$idx]=$v;}if($row){ksort($row);$out[]=$row;}}$z->close();return $out;
}
function sipacak_excel_date(string $v): ?string { $v=trim($v);if($v==='')return null;if(is_numeric($v)&& (float)$v>20000 && (float)$v<80000){$d=new DateTimeImmutable('1899-12-30');return $d->modify('+'.(int)$v.' days')->format('Y-m-d');}foreach(['Y-m-d','d/m/Y','d-m-Y','j/n/Y','d.m.Y'] as $f){$d=DateTime::createFromFormat('!'.$f,$v);if($d&&$d->format($f)===$v)return $d->format('Y-m-d');}$t=strtotime($v);return $t?date('Y-m-d',$t):null;}
